<script setup lang="ts">
import type { AssessmentData } from '../../../../../packages/contracts/v2/assessments/generated'
import { gradeLabels } from '../catalog/presentation'
defineProps<{ result: AssessmentData; historical?: boolean }>()
const emit = defineEmits<{ evidence: [id: string] }>()
const statuses = { eligible: '符合已核查资格条件', ineligible: '明确不满足已核查条件', conditional: '须完成适用后补义务', unknown: '资格未知，仍需核验' }
const validity = { current: '当前证明有效', needs_review: '当前证明需要重新核验', replaced: '发布已被替代', withdrawn: '发布已撤回', unavailable: '当前证明不可用' }
const traceReasons: Record<string,string> = { MATCH: '匹配', NO_MATCH: '不匹配', MISSING: '缺失', PENDING: '待提供', NOT_APPLICABLE: '不适用', CONFLICTED: '有冲突', UNKNOWN_CHILD: '子条件未知', TYPE_MISMATCH: '类型不一致', UNIT_MISMATCH: '单位不一致', SCALE_MISMATCH: '满分不一致', PRECISION_MISMATCH: '精度不一致', CALENDAR_MISMATCH: '日历不一致', REFERENCE_MISSING: '参考时刻缺失', PREDICTED_NOT_ACHIEVED: '预测不能替代实得' }
const deadlineStatus = { before: '当前判断在期限前', expired: '已过期', not_applicable: '明确不适用', unknown: '未知' }
</script>
<template>
  <article class="assessment" :class="result.current_validity === 'current' ? result.eligibility.status : 'historical-invalid'" data-testid="assessment-result">
    <header><div><p class="kicker">{{ historical ? '不可变历史评估' : '本次资格评估' }}</p><h3 data-testid="assessment-status">{{ historical || result.current_validity !== 'current' ? '原评估：' : '' }}{{ statuses[result.eligibility.status] }}</h3></div><span class="validity" data-testid="current-validity">{{ validity[result.current_validity] }}</span></header>
    <p v-if="result.profile_is_synthetic || result.catalogue_is_synthetic" class="demo"><strong>DEMO · 合成评估</strong>，不是真实招生资格或录取依据。</p>
    <p v-if="result.current_validity !== 'current'" class="caution">下列结论保留原评估结果；当前证明已失效或不完整，不能当作当前资格。</p>
    <p class="note">资格结果不代表录取、竞争力、偏好匹配或申请成功；不会自动提交申请。</p>
    <dl class="references"><div><dt>评估 ID</dt><dd>{{ result.assessment_id }}</dd></div><div><dt>原评估时刻</dt><dd>{{ result.assessment_at }}</dd></div><div><dt>画像确认版本</dt><dd>{{ result.profile_id }} · 第 {{ result.profile_version }} 版 · {{ result.profile_version_id }}</dd></div><div><dt>发布 / 阶段</dt><dd>{{ result.release_id }} · {{ result.stage === 'application' ? '申请阶段' : '入学阶段' }}</dd></div><div><dt>规则 / 要求快照</dt><dd>{{ result.ruleset_version ?? '未知' }} / {{ result.requirements_version }}</dd></div><div><dt>结果原因</dt><dd>{{ result.eligibility.reason }}</dd></div></dl>
    <section v-if="result.eligibility.obligations.length" class="obligations"><h4>确实需要完成的后补事项</h4><article v-for="item in result.eligibility.obligations" :key="item.assessment_key"><strong>{{ gradeLabels[item.assessment_key] ?? item.assessment_key }} · 实得记录</strong><p>政策 {{ item.deferral.policy_id }} · 版本 {{ item.deferral.policy_version }} · {{ item.deferral.reason }}</p><p>主申请期限：{{ deadlineStatus[item.deferral.application_deadline_status] }} · 事件 {{ item.deferral.application_deadline_event_id ?? '未提供 / 不适用' }}</p><p>后补期限：{{ deadlineStatus[item.deferral.supplement_deadline_status] }} · 事件 {{ item.deferral.supplement_deadline_event_id ?? '未知' }}</p><p class="note">此响应仅提供期限状态和事件引用，没有官方截止日期或时刻；请核对公开原文，不补造 23:59。</p><button v-for="id in item.deferral.evidence_ids" :key="id" type="button" class="evidence-button" :data-testid="`assessment-evidence-${id}`" @click="emit('evidence',id)">尝试读取此发布的公开证据</button></article></section>
    <div class="dimensions"><section><h4>历史竞争</h4><p>未知 · 没有可用数据</p></section><section><h4>偏好匹配</h4><p>未知 · 没有可用数据</p></section><section><h4>数据质量</h4><p>未知 · 没有可用数据</p></section></div>
    <details class="trace"><summary>查看确定性规则轨迹</summary><p v-if="!result.eligibility.evaluation">没有可用规则表达式，不生成虚假轨迹。</p><template v-else><p>原表达式：{{ result.eligibility.evaluation.truth }} · {{ traceReasons[result.eligibility.evaluation.reason] }}</p><ol><li v-for="(node,index) in result.eligibility.evaluation.trace" :key="index"><strong>{{ node.op }}</strong> · {{ node.field ? node.field.name === 'assessment' ? `${gradeLabels[node.field.key ?? ''] ?? node.field.key} / ${node.field.basis === 'achieved' ? '实得' : '预测'}` : node.field.name : '组合条件' }} · {{ node.outcome }} · {{ traceReasons[node.reason] }}<small v-if="node.children.length">子节点：{{ node.children.join('、') }}</small></li></ol></template></details>
    <details class="proof"><summary>查看绑定指纹</summary><dl class="references"><div><dt>画像 SHA256</dt><dd>{{ result.profile_sha256 }}</dd></div><div><dt>范围 SHA256</dt><dd>{{ result.target.scope_sha256 }}</dd></div><div><dt>结果 SHA256</dt><dd>{{ result.result_sha256 }}</dd></div><div><dt>项目 / 版本</dt><dd>{{ result.target.offering_id }} / {{ result.target.offering_version }}</dd></div></dl></details>
  </article>
</template>
